// This registry describes the site's UI. sourceAction is documentation, never a client URL.
// Product, order, organization and session IDs must come from an authorized server context.
export type SiteFormField = {
  name: string;
  label: string;
  type: 'text' | 'email' | 'tel' | 'password' | 'otp' | 'textarea' | 'select' | 'date' | 'file' | 'checkbox' | 'number' | 'media-selection';
  required: boolean;
  placeholder?: string;
  hint?: string;
  options?: { value: string; label: string }[];
  awaitingOptions?: string;
  multiple?: boolean;
  readOnly?: boolean;
  maxLength?: number;
  minLength?: number;
  minValue?: number;
  maxValue?: number;
  maxUtf8Bytes?: number;
  acceptedExtensions?: string[];
  maxBytes?: number;
  maxFiles?: number;
  // Upload-service contract, not a claim that DocumentPicker inspects file contents/duration.
  serverFileValidation?: { acceptedMimeTypes: string[]; maxVideoDurationSeconds: number; rejectUnreadableVideo: true };
  audience?: 'personal' | 'business';
  sourceName?: string;
  sourceValue?: string;
  requiredFrom?: 'html' | 'handler' | 'database';
  sourceMapping?: 'exact' | 'database' | 'unnamed-source-control' | 'otp-digits' | 'order-property';
};
export type SiteConsent = {
  name: string;
  label: string;
  required: boolean;
  documents: LegalDocumentId[];
  initial: boolean;
};
export type SiteFormDefinition = {
  id: string;
  title: string;
  description: string;
  submitLabel: string;
  fields: SiteFormField[];
  consents: SiteConsent[];
  sourceFiles: string[];
  sourceAction?: string;
  relatedForms?: string[];
  notice?: string;
  externalCapture?: 'payment-provider';
  group?: 'auth' | 'profile' | 'business' | 'service' | 'purchase' | 'marketing';
  legalDocuments?: LegalDocumentId[];
  sourceContext?: string[];
  sourceUrls?: string[];
  sourceNotes?: string[];
  aliasOf?: string;
  awaitingFields?: string;
  repeatedFields?: { name: string; label: string; sourcePattern: string; fields: SiteFormField[] }[];
  // Bitrix's form.result.new templates render a per-form "agree_policy_<suffix>"
  // checkbox (confirmed against site-source for callback/buy-one-click/rent/
  // leasing/found-cheaper/tour/advice) - not a single shared field. Leave unset
  // (keeps the 'agree_privacy' default) for forms not yet verified against the
  // real template/handler pair, or submissions will fail Bitrix's own
  // validateConsentFields() check for the policy checkbox.
  privacyConsentSuffix?: string;
};

