export const siteForms: Record<string, SiteFormDefinition> = Object.fromEntries(definitions.map(definition => [definition.id, definition]));
// These entry points reuse a source form, without inventing a new set of fields or handler.
for (const [id, title, original] of [
  ['quote', 'Запросить предложение', 'business-advice'],
  ['production-request', 'Заказать продукцию собственного производства', 'business-advice'],
  ['contact', 'Связаться с нами', 'callback'],
  ['franchise', 'Стать партнёром', 'partner'],
] as const) siteForms[id] = { ...siteForms[original], id, title, aliasOf: original, consents: siteForms[original].consents.map(consent => ({ ...consent, label: consent.documents.includes('consent') ? legalCopy.processing.replace('[КОНКРЕТНАЯ ЦЕЛЬ ФОРМЫ]', consentPurposes[id]) : consent.label })) };
export const siteFormList: SiteFormDefinition[] = Object.values(siteForms);

// The universal business request is separate from a specification-only quote.
export const businessRequestConsents = siteForms.quote.consents.map(consent => ({ ...consent, label: consent.documents.includes('consent') ? legalCopy.processing.replace('[КОНКРЕТНАЯ ЦЕЛЬ ФОРМЫ]', 'рассмотрения моей заявки для бизнеса и подготовки ответа') : consent.label }));

export const businessCheckoutConsents = siteForms.checkout.consents.filter(consent => !consent.documents.includes('offer'));
export const businessCheckoutForm = { ...siteForms.checkout, consents: businessCheckoutConsents };
